export type Point = {
  x: number;
  y: number;
};

export type PhysicalPoint = Point;

export type WindowDragHost = {
  cursorPosition(): Promise<PhysicalPoint>;
  setPosition(position: PhysicalPoint): Promise<void>;
  startDrag(): void | Promise<void>;
  finishDrag(): Promise<void>;
};

export type WindowDragOutcome = {
  kind: "click" | "drag" | "cancel";
  completion: Promise<void> | null;
};

type ActiveDrag = {
  pointerId: number;
  startPoint: Point;
  latestPoint: Point;
  grabOffset: PhysicalPoint;
  startedAt: number;
  isDragging: boolean;
  startTask: Promise<boolean>;
  needsMove: boolean;
  moveTask: Promise<void> | null;
  firstMoveError: unknown | null;
  isFinishing: boolean;
};

export class WindowDragController {
  private active: ActiveDrag | null = null;

  constructor(
    private readonly host: WindowDragHost,
    private readonly thresholdPx = 4,
    private readonly clickMaxMs = 280,
  ) {}

  get isDragging(): boolean {
    return this.active?.isDragging ?? false;
  }

  begin(pointerId: number, point: Point, grabOffset: PhysicalPoint, startedAt: number): boolean {
    if (this.active) return false;
    this.active = {
      pointerId,
      startPoint: point,
      latestPoint: point,
      grabOffset,
      startedAt,
      isDragging: false,
      startTask: Promise.resolve(true),
      needsMove: false,
      moveTask: null,
      firstMoveError: null,
      isFinishing: false,
    };
    return true;
  }

  move(pointerId: number, point: Point): boolean {
    const drag = this.active;
    if (!drag || drag.pointerId !== pointerId || drag.isFinishing) return false;
    drag.latestPoint = point;
    if (!drag.isDragging && this.movedBeyondThreshold(drag)) {
      this.start(drag);
      return true;
    }
    if (drag.isDragging) this.queueMove(drag);
    return false;
  }

  finish(
    pointerId: number,
    point: Point,
    allowClick: boolean,
    now: number,
  ): WindowDragOutcome | null {
    const drag = this.active;
    if (!drag || drag.pointerId !== pointerId || drag.isFinishing) return null;

    drag.isFinishing = true;
    drag.latestPoint = point;
    if (!drag.isDragging && this.movedBeyondThreshold(drag)) this.start(drag);
    if (!drag.isDragging) {
      this.active = null;
      return {
        kind: allowClick && now - drag.startedAt <= this.clickMaxMs ? "click" : "cancel",
        completion: null,
      };
    }

    this.queueMove(drag);
    const completion = this.finishAfterFinalMove(drag).finally(() => {
      if (this.active === drag) this.active = null;
    });
    return { kind: "drag", completion };
  }

  private movedBeyondThreshold(drag: ActiveDrag): boolean {
    return Math.abs(drag.latestPoint.x - drag.startPoint.x) > this.thresholdPx
      || Math.abs(drag.latestPoint.y - drag.startPoint.y) > this.thresholdPx;
  }

  private start(drag: ActiveDrag): void {
    drag.isDragging = true;
    try {
      drag.startTask = Promise.resolve(this.host.startDrag()).then(
        () => true,
        (error) => {
          if (drag.firstMoveError === null) drag.firstMoveError = error;
          return false;
        },
      );
    } catch (error) {
      if (drag.firstMoveError === null) drag.firstMoveError = error;
      drag.startTask = Promise.resolve(false);
    }
    this.queueMove(drag);
  }

  private queueMove(drag: ActiveDrag): void {
    drag.needsMove = true;
    if (drag.moveTask) return;

    const task = this.moveToLatestCursorPosition(drag);
    drag.moveTask = task;
    void task.finally(() => {
      if (drag.moveTask === task) drag.moveTask = null;
    });
  }

  private async moveToLatestCursorPosition(drag: ActiveDrag): Promise<void> {
    if (!await drag.startTask) return;
    while (drag.needsMove) {
      drag.needsMove = false;
      try {
        const cursor = await this.host.cursorPosition();
        await this.host.setPosition({
          x: cursor.x - drag.grabOffset.x,
          y: cursor.y - drag.grabOffset.y,
        });
      } catch (error) {
        if (drag.firstMoveError === null) drag.firstMoveError = error;
      }
    }
  }

  private async finishAfterFinalMove(drag: ActiveDrag): Promise<void> {
    while (drag.moveTask) {
      const task = drag.moveTask;
      await task;
      if (drag.moveTask === task) break;
    }
    await this.host.finishDrag();
    if (drag.firstMoveError !== null) throw drag.firstMoveError;
  }
}
import { describe, expect, it, vi } from "vitest";

type Point = { x: number; y: number };
type DragHost = {
  cursorPosition(): Promise<Point>;
  setPosition(position: Point): Promise<void>;
  startDrag(): void | Promise<void>;
  finishDrag(): Promise<void>;
};
type DragOutcome = {
  kind: "click" | "drag" | "cancel";
  completion: Promise<void> | null;
};
type DragController = {
  begin(pointerId: number, point: Point, grabOffset: Point, startedAt: number): boolean;
  move(pointerId: number, point: Point): boolean;
  finish(pointerId: number, point: Point, allowClick: boolean, now: number): DragOutcome | null;
};
type DragModule = {
  WindowDragController: new (host: DragHost, thresholdPx?: number, clickMaxMs?: number) => DragController;
};

const dragModulePath = "./window-drag";

async function createController(host: DragHost): Promise<DragController> {
  const module = await import(/* @vite-ignore */ dragModulePath).catch(() => null);
  expect(module).not.toBeNull();
  return new (module as DragModule).WindowDragController(host);
}

function deferred<T>() {
  let resolve: (value: T) => void;
  const promise = new Promise<T>((r) => { resolve = r; });
  return { promise, resolve: resolve! };
}

describe("window pointer drag controller", () => {
  it("keeps drag state active until the queued final window move completes", async () => {
    const firstMove = deferred<void>();
    const finalMove = deferred<void>();
    const host: DragHost = {
      cursorPosition: vi.fn()
        .mockResolvedValueOnce({ x: 120, y: 130 })
        .mockResolvedValueOnce({ x: 2600, y: 480 }),
      setPosition: vi.fn()
        .mockImplementationOnce(() => firstMove.promise)
        .mockImplementationOnce(() => finalMove.promise),
      startDrag: vi.fn(),
      finishDrag: vi.fn().mockResolvedValue(undefined),
    };
    const drag = await createController(host);

    expect(drag.begin(7, { x: 10, y: 20 }, { x: 20, y: 30 }, 0)).toBe(true);
    expect(drag.move(7, { x: 20, y: 20 })).toBe(true);
    await vi.waitFor(() => expect(host.setPosition).toHaveBeenCalledWith({ x: 100, y: 100 }));
    expect(host.startDrag).toHaveBeenCalledTimes(1);

    const result = drag.finish(7, { x: 30, y: 20 }, true, 80);
    expect(result?.kind).toBe("drag");
    expect(drag.begin(8, { x: 40, y: 20 }, { x: 20, y: 30 }, 90)).toBe(false);
    expect(host.finishDrag).not.toHaveBeenCalled();

    firstMove.resolve();
    await vi.waitFor(() => expect(host.setPosition).toHaveBeenCalledWith({ x: 2580, y: 450 }));
    expect(host.finishDrag).not.toHaveBeenCalled();

    finalMove.resolve();
    await result?.completion;
    expect(host.finishDrag).toHaveBeenCalledTimes(1);
    expect(drag.begin(8, { x: 40, y: 20 }, { x: 20, y: 30 }, 90)).toBe(true);
  });

  it("does not move the window before asynchronous drag setup completes", async () => {
    const setup = deferred<void>();
    const host: DragHost = {
      cursorPosition: vi.fn().mockResolvedValue({ x: 120, y: 130 }),
      setPosition: vi.fn().mockResolvedValue(undefined),
      startDrag: vi.fn(() => setup.promise),
      finishDrag: vi.fn().mockResolvedValue(undefined),
    };
    const drag = await createController(host);

    drag.begin(1, { x: 0, y: 0 }, { x: 20, y: 30 }, 0);
    drag.move(1, { x: 8, y: 0 });
    await Promise.resolve();
    expect(host.setPosition).not.toHaveBeenCalled();

    setup.resolve();
    await vi.waitFor(() => expect(host.setPosition).toHaveBeenCalledWith({ x: 100, y: 100 }));
