export type PetInteractionLeaseHost = {
  activate(): Promise<void>;
  deactivate(): Promise<void>;
  reportError(error: unknown): void;
};

type ActiveLease = {
  generation: number;
  activation: Promise<void>;
};

export class PetInteractionLease {
  private active: ActiveLease | null = null;
  private nextGeneration = 0;

  constructor(private readonly host: PetInteractionLeaseHost) {}

  begin(): void {
    let activation: Promise<void>;
    try {
      activation = Promise.resolve(this.host.activate());
    } catch (error) {
      activation = Promise.reject(error);
    }
    const lease = { generation: ++this.nextGeneration, activation };
    this.active = lease;
    void activation.catch((error) => this.host.reportError(error));
  }

  wait(): Promise<void> {
    if (!this.active) return Promise.reject(new Error("Pet interaction lease was not acquired"));
    return this.active.activation;
  }

  async finish(): Promise<void> {
    const lease = this.active;
    if (!lease) return;

    try {
      await lease.activation;
    } catch {
      // Activation failures are reported in begin; cleanup must still run.
    }
    if (this.active !== lease) return;

    this.active = null;
    await this.host.deactivate();
  }
}
import { describe, expect, it, vi } from "vitest";

type LeaseHost = {
  activate(): Promise<void>;
  deactivate(): Promise<void>;
  reportError(error: unknown): void;
};
type Lease = {
  begin(): void;
  wait(): Promise<void>;
  finish(): Promise<void>;
};
type LeaseModule = {
  PetInteractionLease: new (host: LeaseHost) => Lease;
};

const leaseModulePath = "./pet-interaction-lease";

async function createLease(host: LeaseHost): Promise<Lease> {
  const module = await import(/* @vite-ignore */ leaseModulePath).catch(() => null);
  expect(module).not.toBeNull();
  return new (module as LeaseModule).PetInteractionLease(host);
}

function deferred<T>() {
  let resolve: (value: T) => void;
  const promise = new Promise<T>((r) => { resolve = r; });
  return { promise, resolve: resolve! };
}

describe("pet interaction lease", () => {
  it("does not let a late first release deactivate a newer gesture", async () => {
    const firstActivation = deferred<void>();
    const secondActivation = deferred<void>();
    const host: LeaseHost = {
      activate: vi.fn()
        .mockReturnValueOnce(firstActivation.promise)
        .mockReturnValueOnce(secondActivation.promise),
      deactivate: vi.fn().mockResolvedValue(undefined),
      reportError: vi.fn(),
    };
    const lease = await createLease(host);

    lease.begin();
    expect(host.activate).toHaveBeenCalledTimes(1);
    const firstFinish = lease.finish();
    lease.begin();
    firstActivation.resolve();
    await firstFinish;

    expect(host.deactivate).not.toHaveBeenCalled();

    secondActivation.resolve();
    await lease.finish();
    expect(host.deactivate).toHaveBeenCalledTimes(1);
  });

  it("releases a failed acquisition so the native interaction state cannot remain stale", async () => {
    const failure = new Error("native lease failed");
    const host: LeaseHost = {
      activate: vi.fn().mockRejectedValue(failure),
      deactivate: vi.fn().mockResolvedValue(undefined),
      reportError: vi.fn(),
    };
    const lease = await createLease(host);

    lease.begin();
    await lease.finish();

    expect(host.reportError).toHaveBeenCalledWith(failure);
    expect(host.deactivate).toHaveBeenCalledTimes(1);
  });
});
import type { PhysicalPoint, Point, WindowDragOutcome } from "./window-drag";

export type PetPointerDrag = {
  begin(pointerId: number, point: Point, grabOffset: PhysicalPoint, startedAt: number): boolean;
  move(pointerId: number, point: Point): boolean;
  finish(pointerId: number, point: Point, allowClick: boolean, now: number): WindowDragOutcome | null;
};

export type PetPointerOptions = {
  drag: PetPointerDrag;
  canBegin(event: PointerEvent): boolean;
  onBegin(): void;
  finishCapture(): Promise<void>;
  onClick(): void;
  now(): number;
  scale(): number;
  reportError(error: unknown): void;
};

function gesturePoint(event: PointerEvent): Point {
  return { x: event.screenX, y: event.screenY };
}

function physicalGrabOffset(event: PointerEvent, scale: number): PhysicalPoint {
  return { x: event.clientX * scale, y: event.clientY * scale };
}

export function attachPetPointerDrag(element: HTMLElement, options: PetPointerOptions): void {
  let activePointerId: number | null = null;

  function finish(event: PointerEvent, allowClick: boolean): void {
    if (activePointerId !== event.pointerId) return;
    const outcome = options.drag.finish(event.pointerId, gesturePoint(event), allowClick, options.now());
    activePointerId = null;
    if (element.hasPointerCapture(event.pointerId)) element.releasePointerCapture(event.pointerId);
    if (!outcome) return;
    if (outcome.kind === "click") {
      void options.finishCapture().catch(options.reportError);
      options.onClick();
      return;
    }
    if (outcome.kind === "cancel") {
      void options.finishCapture().catch(options.reportError);
      return;
    }
    if (outcome.completion) void outcome.completion.catch(options.reportError);
  }

  element.addEventListener("pointerdown", (event) => {
    if (event.button !== 0 || activePointerId !== null || !options.canBegin(event)) return;

    if (!options.drag.begin(
      event.pointerId,
      gesturePoint(event),
      physicalGrabOffset(event, options.scale()),
      options.now(),
    )) return;
    options.onBegin();
    event.preventDefault();
    activePointerId = event.pointerId;
    element.setPointerCapture(event.pointerId);
  });

