import {
  WindowDragController,
  type PhysicalPoint,
  type Point,
  type WindowDragHost,
  type WindowDragOutcome,
} from "./window-drag";

export type { PhysicalPoint, Point };

export type FloatingBallDragHost = Omit<WindowDragHost, "startDrag" | "finishDrag"> & {
  persistPosition(): Promise<void>;
};

export type FloatingBallDragOutcome = WindowDragOutcome;

export class FloatingBallDragController extends WindowDragController {
  constructor(host: FloatingBallDragHost, thresholdPx = 4, clickMaxMs = 280) {
    super({
      cursorPosition: () => host.cursorPosition(),
      setPosition: (position) => host.setPosition(position),
      startDrag: () => {},
      finishDrag: () => host.persistPosition(),
    }, thresholdPx, clickMaxMs);
  }
}
import { describe, expect, it, vi } from "vitest";

type Point = { x: number; y: number };
type DragHost = {
  cursorPosition(): Promise<Point>;
  setPosition(position: Point): Promise<void>;
  persistPosition(): Promise<void>;
};
type DragOutcome = {
  kind: "click" | "drag" | "cancel";
  completion: Promise<void> | null;
};
type DragController = {
  readonly isDragging: boolean;
  begin(pointerId: number, point: Point, grabOffset: Point, startedAt: number): boolean;
  move(pointerId: number, point: Point): boolean;
  finish(pointerId: number, point: Point, allowClick: boolean, now: number): DragOutcome | null;
};
type DragModule = {
  FloatingBallDragController: new (host: DragHost, thresholdPx?: number, clickMaxMs?: number) => DragController;
};

const dragModulePath = "./floating-ball-drag";

async function createController(host: DragHost): Promise<DragController> {
  const module = await import(/* @vite-ignore */ dragModulePath).catch(() => null);
  expect(module).not.toBeNull();
  return new (module as DragModule).FloatingBallDragController(host);
}

function deferred<T>() {
  let resolve: (value: T) => void;
  const promise = new Promise<T>((r) => { resolve = r; });
  return { promise, resolve: resolve! };
}

describe("floating ball pointer drag", () => {
  it("keeps a short stationary press as a menu click", async () => {
    const host: DragHost = {
      cursorPosition: vi.fn(),
      setPosition: vi.fn(),
      persistPosition: vi.fn(),
    };
    const drag = await createController(host);

    expect(drag.begin(1, { x: 40, y: 50 }, { x: 20, y: 30 }, 100)).toBe(true);
    const result = drag.finish(1, { x: 42, y: 53 }, true, 200);

    expect(result).toEqual({ kind: "click", completion: null });
    expect(host.cursorPosition).not.toHaveBeenCalled();
    expect(host.setPosition).not.toHaveBeenCalled();
    expect(host.persistPosition).not.toHaveBeenCalled();
  });

  it("uses physical cursor coordinates and persists only after the final move", async () => {
    const firstMove = deferred<void>();
    const finalMove = deferred<void>();
    const host: DragHost = {
      cursorPosition: vi.fn()
        .mockResolvedValueOnce({ x: 120, y: 130 })
        .mockResolvedValueOnce({ x: 2600, y: 480 }),
      setPosition: vi.fn()
        .mockImplementationOnce(() => firstMove.promise)
        .mockImplementationOnce(() => finalMove.promise),
      persistPosition: vi.fn().mockResolvedValue(undefined),
    };
    const drag = await createController(host);

    drag.begin(7, { x: 10, y: 20 }, { x: 20, y: 30 }, 0);
    expect(drag.move(7, { x: 20, y: 20 })).toBe(true);
    await vi.waitFor(() => expect(host.setPosition).toHaveBeenCalledWith({ x: 100, y: 100 }));

    const result = drag.finish(7, { x: 30, y: 20 }, true, 80);
    expect(result?.kind).toBe("drag");
    expect(host.persistPosition).not.toHaveBeenCalled();

    firstMove.resolve();
    await vi.waitFor(() => expect(host.setPosition).toHaveBeenCalledWith({ x: 2580, y: 450 }));
    expect(host.persistPosition).not.toHaveBeenCalled();

    finalMove.resolve();
    await result?.completion;
    expect(host.persistPosition).toHaveBeenCalledTimes(1);
  });

  it("surfaces an earlier move failure after a later final move persists", async () => {
    const moveFailure = new Error("native move failed");
    const host: DragHost = {
      cursorPosition: vi.fn()
        .mockResolvedValueOnce({ x: 120, y: 130 })
        .mockResolvedValue({ x: 260, y: 370 }),
      setPosition: vi.fn()
        .mockImplementationOnce(() => { throw moveFailure; })
        .mockResolvedValueOnce(undefined),
      persistPosition: vi.fn().mockResolvedValue(undefined),
    };
    const drag = await createController(host);

    drag.begin(5, { x: 0, y: 0 }, { x: 20, y: 30 }, 0);
    expect(drag.move(5, { x: 8, y: 0 })).toBe(true);
    await vi.waitFor(() => expect(host.setPosition).toHaveBeenCalledTimes(1));

    drag.move(5, { x: 12, y: 0 });
    const result = drag.finish(5, { x: 16, y: 0 }, true, 40);
    expect(result?.kind).toBe("drag");
    await expect(result!.completion).rejects.toBe(moveFailure);
    expect(host.persistPosition).toHaveBeenCalledTimes(1);
  });

  it("persists a cancelled drag without turning it into a click", async () => {
    const host: DragHost = {
      cursorPosition: vi.fn().mockResolvedValue({ x: 240, y: 360 }),
      setPosition: vi.fn().mockResolvedValue(undefined),
      persistPosition: vi.fn().mockResolvedValue(undefined),
    };
    const drag = await createController(host);

    drag.begin(3, { x: 0, y: 0 }, { x: 10, y: 10 }, 0);
    expect(drag.move(3, { x: 8, y: 0 })).toBe(true);
    const result = drag.finish(3, { x: 12, y: 0 }, false, 20);

    expect(result?.kind).toBe("drag");
    await result?.completion;
    expect(drag.isDragging).toBe(false);
    expect(host.setPosition).toHaveBeenLastCalledWith({ x: 230, y: 350 });
    expect(host.persistPosition).toHaveBeenCalledTimes(1);
  });
});
import type { FloatingBallDragOutcome, PhysicalPoint, Point } from "./floating-ball-drag";

export type FloatingBallPointerDrag = {
  begin(pointerId: number, point: Point, grabOffset: PhysicalPoint, startedAt: number): boolean;
  move(pointerId: number, point: Point): boolean;
  finish(pointerId: number, point: Point, allowClick: boolean, now: number): FloatingBallDragOutcome | null;
};

export type FloatingBallPointerOptions = {
  drag: FloatingBallPointerDrag;
  isMenuOpen(): boolean;
  hideMenu(): void;
  showMenu(): void;
  now(): number;
  scale(): number;
  reportError(error: unknown): void;
};

function gesturePoint(e: PointerEvent): Point {
  return { x: e.screenX, y: e.screenY };
}

function physicalGrabOffset(e: PointerEvent, scale: number): PhysicalPoint {
  return { x: e.clientX * scale, y: e.clientY * scale };
}

export function attachFloatingBallPointerDrag(ball: HTMLElement, options: FloatingBallPointerOptions): void {
  let activePointerId: number | null = null;

  function finish(e: PointerEvent, allowClick: boolean): void {
    if (activePointerId !== e.pointerId) return;
    const outcome = options.drag.finish(e.pointerId, gesturePoint(e), allowClick, options.now());
    activePointerId = null;
    ball.classList.remove("pressed", "dragging");
    if (ball.hasPointerCapture(e.pointerId)) ball.releasePointerCapture(e.pointerId);
    if (!outcome) return;
    if (outcome.kind === "click") {
      options.showMenu();
      return;
    }
    if (outcome.completion) void outcome.completion.catch(options.reportError);
  }

  ball.addEventListener("pointerdown", (e) => {
    if (e.button !== 0) return;
    if (options.isMenuOpen()) {
      options.hideMenu();
      return;
    }
    if (activePointerId !== null) return;

    e.preventDefault();
    if (!options.drag.begin(e.pointerId, gesturePoint(e), physicalGrabOffset(e, options.scale()), options.now())) return;
    activePointerId = e.pointerId;
    ball.setPointerCapture(e.pointerId);
    ball.classList.add("pressed");
  });

  ball.addEventListener("pointermove", (e) => {
    if (activePointerId !== e.pointerId) return;
    if (options.drag.move(e.pointerId, gesturePoint(e))) {
      ball.classList.remove("pressed");
      ball.classList.add("dragging");
    }
  });

  ball.addEventListener("pointerup", (e) => finish(e, true));
  ball.addEventListener("pointercancel", (e) => finish(e, false));
  ball.addEventListener("lostpointercapture", (e) => finish(e, false));
}
import { describe, expect, it, vi } from "vitest";

type Point = { x: number; y: number };
type DragOutcome = {
  kind: "click" | "drag" | "cancel";
  completion: Promise<void> | null;
};
type DragController = {
  begin(pointerId: number, point: Point, grabOffset: Point, startedAt: number): boolean;
  move(pointerId: number, point: Point): boolean;
  finish(pointerId: number, point: Point, allowClick: boolean, now: number): DragOutcome | null;
};
type PointerOptions = {
  drag: DragController;
  isMenuOpen(): boolean;
  hideMenu(): void;
  showMenu(): void;
  now(): number;
  scale(): number;
  reportError(error: unknown): void;
};
type PointerModule = {
  attachFloatingBallPointerDrag(ball: HTMLElement, options: PointerOptions): void;
};

const pointerModulePath = "./floating-ball-pointer";

async function attach(ball: FakeBall, options: PointerOptions): Promise<void> {
  const module = await import(/* @vite-ignore */ pointerModulePath).catch(() => null);
  expect(module).not.toBeNull();
  (module as PointerModule).attachFloatingBallPointerDrag(ball as unknown as HTMLElement, options);
}

class FakeBall {
  readonly captured = new Set<number>();
  readonly classes = new Set<string>();
  private readonly listeners = new Map<string, (event: PointerEvent) => void>();

  readonly classList = {
    add: (...names: string[]) => names.forEach((name) => this.classes.add(name)),
    remove: (...names: string[]) => names.forEach((name) => this.classes.delete(name)),
  };

  addEventListener(type: string, listener: (event: PointerEvent) => void): void {
    this.listeners.set(type, listener);
  }

  setPointerCapture(pointerId: number): void {
    this.captured.add(pointerId);
  }

  hasPointerCapture(pointerId: number): boolean {
    return this.captured.has(pointerId);
  }

  releasePointerCapture(pointerId: number): void {
    this.captured.delete(pointerId);
  }

  dispatch(type: string, event: PointerEvent): void {
    this.listeners.get(type)?.(event);
  }
}

function pointerEvent(overrides: Partial<PointerEvent> = {}): PointerEvent {
  return {
    pointerId: 1,
    button: 0,
    screenX: 100,
    screenY: 200,
    clientX: 10,
    clientY: 20,
    preventDefault: vi.fn(),
    ...overrides,
  } as PointerEvent;
}

function options(drag: DragController, overrides: Partial<PointerOptions> = {}): PointerOptions {
  return {
    drag,
    isMenuOpen: vi.fn().mockReturnValue(false),
    hideMenu: vi.fn(),
    showMenu: vi.fn(),
    now: vi.fn().mockReturnValue(500),
    scale: vi.fn().mockReturnValue(1.5),
    reportError: vi.fn(),
    ...overrides,
  };
}

describe("floating ball pointer binding", () => {
  it("captures a pointer, starts dragging, then releases it without duplicate completion", async () => {
    const drag: DragController = {
      begin: vi.fn().mockReturnValue(true),
      move: vi.fn().mockReturnValue(true),
      finish: vi.fn().mockReturnValue({ kind: "click", completion: null }),
    };
    const ball = new FakeBall();
    const config = options(drag);
    await attach(ball, config);

    const down = pointerEvent();
    ball.dispatch("pointerdown", down);
    expect(down.preventDefault).toHaveBeenCalledTimes(1);
    expect(drag.begin).toHaveBeenCalledWith(1, { x: 100, y: 200 }, { x: 15, y: 30 }, 500);
    expect(ball.captured).toContain(1);
    expect(ball.classes).toContain("pressed");

    ball.dispatch("pointermove", pointerEvent({ screenX: 110 }));
    expect(drag.move).toHaveBeenCalledWith(1, { x: 110, y: 200 });
    expect(ball.classes).not.toContain("pressed");
    expect(ball.classes).toContain("dragging");

    ball.dispatch("pointerup", pointerEvent({ screenX: 120 }));
    expect(drag.finish).toHaveBeenCalledWith(1, { x: 120, y: 200 }, true, 500);
    expect(config.showMenu).toHaveBeenCalledTimes(1);
    expect(ball.captured).not.toContain(1);
    expect(ball.classes).not.toContain("dragging");

    ball.dispatch("lostpointercapture", pointerEvent({ screenX: 120 }));
    expect(drag.finish).toHaveBeenCalledTimes(1);
  });

  it("cancels a drag without opening the menu and reports asynchronous failures", async () => {
    const failure = new Error("persist failed");
    const completion = Promise.reject(failure);
    void completion.catch(() => {});
    const drag: DragController = {
      begin: vi.fn().mockReturnValue(true),
      move: vi.fn().mockReturnValue(false),
      finish: vi.fn().mockReturnValue({ kind: "drag", completion }),
    };
    const ball = new FakeBall();
    const config = options(drag);
    await attach(ball, config);

    ball.dispatch("pointerdown", pointerEvent({ pointerId: 2 }));
    ball.dispatch("pointercancel", pointerEvent({ pointerId: 2, screenX: 140 }));

    expect(drag.finish).toHaveBeenCalledWith(2, { x: 140, y: 200 }, false, 500);
    expect(config.showMenu).not.toHaveBeenCalled();
    expect(ball.captured).not.toContain(2);
    await vi.waitFor(() => expect(config.reportError).toHaveBeenCalledWith(failure));
  });

  it("closes an open menu instead of beginning a new drag", async () => {
    const drag: DragController = {
      begin: vi.fn().mockReturnValue(true),
      move: vi.fn().mockReturnValue(false),
      finish: vi.fn().mockReturnValue(null),
    };
    const ball = new FakeBall();
    const config = options(drag, { isMenuOpen: vi.fn().mockReturnValue(true) });
    await attach(ball, config);

    ball.dispatch("pointerdown", pointerEvent());

    expect(config.hideMenu).toHaveBeenCalledTimes(1);
    expect(drag.begin).not.toHaveBeenCalled();
    expect(ball.captured).toHaveLength(0);
  });
});
// Floating ball: a draggable desktop orb. Left-click opens a bubble menu,
// right-click opens Settings, drag moves the window and persists its position
// on release.

import "./styles.css";

import { invoke } from "@tauri-apps/api/core";
import { emit, listen } from "@tauri-apps/api/event";
import { cursorPosition, currentMonitor, getCurrentWindow, LogicalPosition, LogicalSize, PhysicalPosition } from "@tauri-apps/api/window";
import { FloatingBallDragController } from "./floating-ball-drag";
import { attachFloatingBallPointerDrag } from "./floating-ball-pointer";
import { t, setLang, type Lang } from "./i18n";
import { Pet } from "./pet";
import { getLibrary } from "./catalog";
import { loadPetStore, selectedPetInstance } from "./pets";

const QUICK_KEY = "ap_quick_bubbles";
const MAX_PRESETS = 12;

const WIN_SIZE = 80;        // window is larger than the 56px orb so shadows/scale fit
const MENU_W = 300;
const MENU_H = 420;

const ball = document.getElementById("ball") as HTMLDivElement;
const menu = document.getElementById("ball-menu") as HTMLDivElement;
const input = document.getElementById("bm-input") as HTMLInputElement;
const presetsEl = document.getElementById("bm-presets") as HTMLDivElement;
const sendBtn = document.getElementById("bm-send") as HTMLButtonElement;
const cancelBtn = document.getElementById("bm-cancel") as HTMLButtonElement;

const win = getCurrentWindow();
const floatingBallDrag = new FloatingBallDragController({
  cursorPosition,
  setPosition: (position) => win.setPosition(new PhysicalPosition(position.x, position.y)),
  persistPosition: () => invoke<void>("persist_floating_ball_position"),
});

let selectedPreset = -1;

function readPresets(): string[] {
  try {
    const v = JSON.parse(localStorage.getItem(QUICK_KEY) || "[]");
    return Array.isArray(v)
      ? v.filter((x: unknown) => typeof x === "string" && x.trim()).slice(0, MAX_PRESETS)
      : [];
  } catch { return []; }
}

function writePresets(list: string[]) {
  localStorage.setItem(QUICK_KEY, JSON.stringify(list.slice(0, MAX_PRESETS)));
  void emit("bubble-changed", null);
}

function syncSend() {
  sendBtn.disabled = !input.value.trim();
}

function createPresetButton(line: string, index: number) {
  const btn = document.createElement("button");
  btn.className = "bm-preset";
  btn.textContent = line;
  btn.title = t("Send to selected") + " · " + t("Shift-click to delete");
  btn.onclick = (ev) => {
    if (ev.shiftKey) {
      const next = readPresets().filter((_, j) => j !== index);
      writePresets(next);
      selectedPreset = -1;
      paintPresets();
      syncSend();
      return;
    }
    selectedPreset = index;
    input.value = line;
    paintPresets();
    syncSend();
    input.focus();
  };
  if (selectedPreset === index) btn.classList.add("sel");
  return btn;
}

function paintPresets() {
  const list = readPresets();
  presetsEl.innerHTML = "";
  if (!list.length) {
    presetsEl.style.display = "none";
    return;
  }
  presetsEl.style.display = "";
  list.forEach((line, i) => presetsEl.appendChild(createPresetButton(line, i)));
}

function applyLangStrings() {
  const bmTitle = document.getElementById("bm-title-text");
  if (bmTitle) bmTitle.textContent = t("Quick bubble");
  const bmHint = document.getElementById("bm-hint");
  if (bmHint) bmHint.textContent = t("Shift-click to remove");
  input.placeholder = t("Type a bubble message…");
  cancelBtn.textContent = t("Cancel");
  sendBtn.textContent = t("Send");
  ball.title = t("Left-click: bubble · Right-click: settings · Drag to move");
}

function shrinkToBall() {
  void win.setSize(new LogicalSize(WIN_SIZE, WIN_SIZE));
}

/// Height delta between the menu window and the ball window.
const MENU_GROW = MENU_H - WIN_SIZE;

async function showMenu() {
  if (!menu.hidden) return;
  input.value = "";
  selectedPreset = -1;
  paintPresets();
  syncSend();

  const pos = await win.outerPosition();
  const sf = await win.scaleFactor();
  const mon = await currentMonitor();
  const work = mon?.workArea;
  const logicalX = pos.x / sf;
  const logicalY = pos.y / sf;
  const workLeft = work ? work.position.x / sf : logicalX;
  const workTop = work ? work.position.y / sf : logicalY;
  const workRight = work ? (work.position.x + work.size.width) / sf : logicalX + MENU_W;
  const workBottom = work ? (work.position.y + work.size.height) / sf : logicalY + MENU_H;

  // If the menu would overflow the bottom, open UPWARD: the ball sticks to
  // the bottom of the window and the menu sits above it. The window's Y
  // moves up by MENU_GROW so the ball's screen position is preserved.
  const openAbove = logicalY + MENU_H > workBottom;
  // Adjust X so the wider menu window stays on-screen.
  let newX = logicalX;
  if (newX + MENU_W > workRight) newX = workRight - MENU_W;
  if (newX < workLeft) newX = workLeft;
  let newY = logicalY;
  if (openAbove) newY = logicalY - MENU_GROW;
  // Clamp Y so the window never starts above the work area.
  if (newY < workTop) newY = workTop;

  document.body.classList.toggle("menu-above", openAbove);
  if (Math.abs(newX - logicalX) > 0.5 || Math.abs(newY - logicalY) > 0.5) {
    void win.setPosition(new LogicalPosition(newX, newY));
  }
  // Resize FIRST, then reveal the menu, so the menu never appears clipped
  // inside the still-80×80 window for a frame.
  await win.setSize(new LogicalSize(MENU_W, MENU_H));
  menu.hidden = false;
  requestAnimationFrame(() => input.focus());
}

function hideMenu() {
  if (menu.hidden) return;
  menu.hidden = true;
  const wasAbove = document.body.classList.contains("menu-above");
  document.body.classList.remove("menu-above");
  shrinkToBall();
  if (wasAbove) {
    // Window was shifted up by MENU_GROW to open the menu above.
    // Move it back down so the ball returns to its original screen position.
    void (async () => {
      const pos = await win.outerPosition();
      const sf = await win.scaleFactor();
      void win.setPosition(new LogicalPosition(pos.x / sf, pos.y / sf + MENU_GROW));
    })();
  }
}

function send() {
  const text = input.value.trim();
  if (!text) return;
  const next = [text, ...readPresets().filter((x) => x !== text)];
  writePresets(next);
  void emit("quick-bubble", { text });
  hideMenu();
}

// ---- click vs drag ---------------------------------------------------------
// Tauri's native startDragging can lose mouseup on Windows, leaving the window
// attached to the cursor. Pointer capture keeps the interaction in the webview.
attachFloatingBallPointerDrag(ball, {
  drag: floatingBallDrag,
  isMenuOpen: () => !menu.hidden,
  hideMenu,
  showMenu,
  now: () => performance.now(),
  scale: () => window.devicePixelRatio,
  reportError: (error) => console.error("Unable to finish floating ball drag", error),
});

ball.addEventListener("contextmenu", (e) => {
  e.preventDefault();
  hideMenu();
  void invoke("open_settings");
});

// ---- menu interactions -----------------------------------------------------
input.addEventListener("input", () => { selectedPreset = -1; paintPresets(); syncSend(); });
input.addEventListener("keydown", (e) => {
  if (e.key === "Enter" && input.value.trim()) { e.preventDefault(); send(); }
  else if (e.key === "Escape") { hideMenu(); }
});

cancelBtn.onclick = () => hideMenu();
sendBtn.onclick = () => send();

// Dismiss menu on Escape or when the window loses focus.
window.addEventListener("keydown", (e) => { if (e.key === "Escape" && !menu.hidden) hideMenu(); });
window.addEventListener("blur", () => { if (!menu.hidden) hideMenu(); });

// ---- live updates ----------------------------------------------------------
function applyReduceMotion() {
  document.body.classList.toggle("reduce-motion", localStorage.getItem("ap_reduce_motion") === "1");
}
applyReduceMotion();
window.addEventListener("storage", (e) => { if (e.key === "ap_reduce_motion") applyReduceMotion(); });

applyLangStrings();
paintPresets();
syncSend();
void listen("bubble-changed", () => paintPresets());
void listen<Lang>("lang-changed", (e) => { setLang(e.payload); applyLangStrings(); paintPresets(); });

// ---- living pet inside the orb: mirror the instance selected in Settings.
const ballCanvas = document.getElementById("ball-pet") as HTMLCanvasElement | null;
let ballPet: Pet | null = null;

function loadBallPet(): void {
  const store = loadPetStore();
  const instance = store ? selectedPetInstance(store) : null;
  const pet = getLibrary().find((candidate) => candidate.slug === instance?.spriteSlug) ?? getLibrary()[0];
  if (pet) ballPet?.load(pet.url);
}

if (ballCanvas) {
  ballPet = new Pet(ballCanvas);
  loadBallPet();
}
void listen("pets-changed", loadBallPet);

