424	    const kx = cr.width / canvas.width;
425	    const ky = cr.height / canvas.height;
426	    rects.push({
427	      left: cr.left + sr.x * kx,
428	      top: cr.top + sr.y * ky,
429	      right: cr.left + (sr.x + sr.w) * kx,
430	      bottom: cr.top + (sr.y + sr.h) * ky,
431	    });
432	  } else {
433	    rects.push({ left: cr.left, top: cr.top, right: cr.right, bottom: cr.bottom });
434	  }
435	  const left = Math.min(...rects.map((r) => r.left));
436	  const top = Math.min(...rects.map((r) => r.top));
437	  const right = Math.max(...rects.map((r) => r.right));
438	  const bottom = Math.max(...rects.map((r) => r.bottom));
439	  const sig = [left, top, right, bottom].map((v) => Math.round(v)).join(",");
440	  if (sig === lastHitSig) return;
441	  lastHitSig = sig;
442	  invoke("set_hit_rect", { label: MY_LABEL, x: left * d, y: top * d, w: (right - left) * d, h: (bottom - top) * d })
443	    .catch((err) => invoke("log_debug", { msg: `set_hit_rect failed: ${err}` }).catch(() => {}));
444	}
445	new ResizeObserver(reportHitRect).observe(petRoot);
446	window.addEventListener("resize", reportHitRect);
447	reportHitRect();
