450	function applyReduceMotion() {
451	  document.body.classList.toggle("reduce-motion", localStorage.getItem("ap_reduce_motion") === "1");
452	}
453	applyReduceMotion();
454	window.addEventListener("storage", (e) => { if (e.key === "ap_reduce_motion") applyReduceMotion(); });
