 20	function gesturePoint(event: PointerEvent): Point {
 21	  return { x: event.screenX, y: event.screenY };
 22	}
 23	
 24	function physicalGrabOffset(event: PointerEvent, scale: number): PhysicalPoint {
 25	  return { x: event.clientX * scale, y: event.clientY * scale };
 26	}
 27	
 28	export function attachPetPointerDrag(element: HTMLElement, options: PetPointerOptions): void {
 29	  let activePointerId: number | null = null;
 30	
 31	  function finish(event: PointerEvent, allowClick: boolean): void {
 32	    if (activePointerId !== event.pointerId) return;
 33	    const outcome = options.drag.finish(event.pointerId, gesturePoint(event), allowClick, options.now());
 34	    activePointerId = null;
 35	    if (element.hasPointerCapture(event.pointerId)) element.releasePointerCapture(event.pointerId);
 36	    if (!outcome) return;
 37	    if (outcome.kind === "click") {
 38	      void options.finishCapture().catch(options.reportError);
 39	      options.onClick();
 40	      return;
 41	    }
 42	    if (outcome.kind === "cancel") {
 43	      void options.finishCapture().catch(options.reportError);
 44	      return;
 45	    }
 46	    if (outcome.completion) void outcome.completion.catch(options.reportError);
 47	  }
 48	
 49	  element.addEventListener("pointerdown", (event) => {
 50	    if (event.button !== 0 || activePointerId !== null || !options.canBegin(event)) return;
 51	
 52	    if (!options.drag.begin(
 53	      event.pointerId,
 54	      gesturePoint(event),
 55	      physicalGrabOffset(event, options.scale()),
 56	      options.now(),
 57	    )) return;
 58	    options.onBegin();
 59	    event.preventDefault();
 60	    activePointerId = event.pointerId;
 61	    element.setPointerCapture(event.pointerId);
 62	  });
 63	
 64	  element.addEventListener("pointermove", (event) => {
 65	    if (activePointerId !== event.pointerId) return;
 66	    options.drag.move(event.pointerId, gesturePoint(event));
 67	  });
 68	
 69	  element.addEventListener("pointerup", (event) => finish(event, true));
 70	  element.addEventListener("pointercancel", (event) => finish(event, false));
 71	  element.addEventListener("lostpointercapture", (event) => finish(event, false));
 72	}
  1	export type PetInteractionLeaseHost = {
  2	  activate(): Promise<void>;
  3	  deactivate(): Promise<void>;
  4	  reportError(error: unknown): void;
  5	};
  6	
  7	type ActiveLease = {
  8	  generation: number;
  9	  activation: Promise<void>;
 10	};
 11	
 12	export class PetInteractionLease {
 13	  private active: ActiveLease | null = null;
 14	  private nextGeneration = 0;
 15	
 16	  constructor(private readonly host: PetInteractionLeaseHost) {}
 17	
 18	  begin(): void {
 19	    let activation: Promise<void>;
 20	    try {
 21	      activation = Promise.resolve(this.host.activate());
 22	    } catch (error) {
 23	      activation = Promise.reject(error);
 24	    }
 25	    const lease = { generation: ++this.nextGeneration, activation };
 26	    this.active = lease;
 27	    void activation.catch((error) => this.host.reportError(error));
 28	  }
 29	
 30	  wait(): Promise<void> {
 31	    if (!this.active) return Promise.reject(new Error("Pet interaction lease was not acquired"));
 32	    return this.active.activation;
 33	  }
 34	
 35	  async finish(): Promise<void> {
 36	    const lease = this.active;
 37	    if (!lease) return;
 38	
 39	    try {
 40	      await lease.activation;
 41	    } catch {
 42	      // Activation failures are reported in begin; cleanup must still run.
 43	    }
 44	    if (this.active !== lease) return;
 45	
 46	    this.active = null;
 47	    await this.host.deactivate();
 48	  }
 49	}

