   1	// The tray/right-click popover, a port of the macOS MenuContentView: Show pet
   2	// toggle, pet-size slider, and a Settings / Updates / Quit footer. Hides
   3	// itself when it loses focus.
   4	
   5	import "./styles.css";
   6	
   7	import { invoke } from "@tauri-apps/api/core";
   8	import { emitTo, listen } from "@tauri-apps/api/event";
   9	import { getCurrentWindow, LogicalSize } from "@tauri-apps/api/window";
  10	import { check } from "@tauri-apps/plugin-updater";
  11	import { relaunch, exit } from "@tauri-apps/plugin-process";
  12	import { t, setLang, type Lang } from "./i18n";
  13	import { Pet } from "./pet";
  14	import { getLibrary } from "./catalog";
  15	import { loadPetStore, savePetStore, selectedPetInstance, updatePetInstance } from "./pets";
  16	
  17	function applyStatic() {
  18	  const set = (id: string, key: string) => { const el = document.getElementById(id); if (el) el.textContent = t(key); };
  19	  set("pop-sub", "Your little companion");
  20	  set("t-pop-showpet", "Show desktop pets");
  21	  set("t-pop-size", "Pet size");
  22	  set("t-pop-settings", "Settings");
  23	  set("t-pop-updates", "Updates");
  24	  set("t-pop-quit", "Quit");
  25	}
  26	
  27	// ---- controls ----------------------------------------------------------------
  28	
  29	const showPet = document.getElementById("pop-showpet") as HTMLInputElement;
  30	invoke<boolean>("get_desktop_pets_visible").then((visible) => { showPet.checked = visible; }).catch(() => { showPet.checked = true; });
  31	showPet.onchange = () => invoke("set_desktop_pets_visible", { visible: showPet.checked }).catch(() => {});
  32	
  33	// Living pet in the popover header: mirror the instance selected in Settings.
  34	const popPetCanvas = document.getElementById("pop-pet") as HTMLCanvasElement | null;
  35	const popPet = popPetCanvas ? new Pet(popPetCanvas) : null;
  36	
  37	function loadPopoverPet(): void {
  38	  const store = loadPetStore();
  39	  const instance = store ? selectedPetInstance(store) : null;
  40	  const pet = getLibrary().find((candidate) => candidate.slug === instance?.spriteSlug) ?? getLibrary()[0];
  41	  if (pet) popPet?.load(pet.url);
  42	}
  43	loadPopoverPet();
  44	
  45	const size = document.getElementById("pop-size") as HTMLInputElement;
  46	function syncSize(): void {
  47	  const store = loadPetStore();
  48	  size.value = String((store ? selectedPetInstance(store) : null)?.size ?? 100);
  49	}
  50	syncSize();
  51	size.oninput = () => {
  52	  const store = loadPetStore();
  53	  if (!store) return;
  54	  const instance = selectedPetInstance(store);
  55	  if (!instance) return;
  56	  savePetStore(updatePetInstance(store, instance.id, { size: parseInt(size.value, 10) }));
  57	  void emitTo(`pet-${instance.id}`, "pet-instance-changed", { instanceId: instance.id }).catch(() => {});
  58	  void emitTo("settings", "pet-instance-changed", { instanceId: instance.id }).catch(() => {});
  59	};
  60	
  61	(document.getElementById("pop-settings") as HTMLButtonElement).onclick = () => {
  62	  invoke("open_settings").catch(() => {});
  63	  void getCurrentWindow().hide();
  64	};
  65	(document.getElementById("pop-quit") as HTMLButtonElement).onclick = () => { exit(0); };
  66	
  67	const updatesBtn = document.getElementById("pop-updates") as HTMLButtonElement;
  68	updatesBtn.onclick = async () => {
  69	  const label = document.getElementById("t-pop-updates")!;
  70	  label.textContent = t("Checking…");
  71	  try {
  72	    const update = await check();
  73	    if (update) {
  74	      label.textContent = t("Installing…");
  75	      await update.downloadAndInstall();
  76	      await relaunch();
  77	    } else {
  78	      label.textContent = t("Up to date");
  79	      setTimeout(() => { label.textContent = t("Updates"); }, 2500);
  80	    }
  81	  } catch {
  82	    label.textContent = t("Up to date");
  83	    setTimeout(() => { label.textContent = t("Updates"); }, 2500);
  84	  }
  85	};
  86	
  87	// ---- lifecycle ----------------------------------------------------------------
  88	
  89	// Hide when clicking anywhere outside (the popover loses focus), like the
  90	// macOS transient popover. Backed up by a Rust-side Focused(false) handler,
  91	// a "popover-close" broadcast from the pet window, and the Escape key.
  92	getCurrentWindow().onFocusChanged(({ payload: focused }) => {
  93	  if (!focused) void getCurrentWindow().hide();
  94	});
  95	listen<Lang>("lang-changed", (event) => {
  96	  setLang(event.payload);
  97	  applyStatic();
  98	});
  99	listen("popover-close", () => void getCurrentWindow().hide());
 100	window.addEventListener("keydown", (e) => {
 101	  if (e.key === "Escape") void getCurrentWindow().hide();
 102	});
 103	
 104	// Re-sync + refresh whenever the popover is shown again.
 105	listen("popover-shown", () => {
 106	  applyStatic();
 107	  syncSize();
 108	  loadPopoverPet();
 109	  invoke<boolean>("get_desktop_pets_visible").then((visible) => { showPet.checked = visible; }).catch(() => {});
 110	});
 111	listen("pets-changed", () => {
 112	  syncSize();
 113	  loadPopoverPet();
 114	});
 115	
 116	// Hug the content height like the macOS popover (no dead space).
 117	let lastH = 0;
 118	function fitWindow() {
 119	  const card = document.querySelector(".pop-card") as HTMLElement;
 120	  if (!card) return;
 121	  const h = Math.min(560, Math.max(220, card.scrollHeight + 20));
 122	  if (Math.abs(h - lastH) < 2) return;
 123	  lastH = h;
 124	  getCurrentWindow().setSize(new LogicalSize(300, h)).catch(() => {});
 125	}
 126	fitWindow();
